// routes/tasks/clientLoader.ts
export function clientLoader() {
  return { tasks: [{ id: "1", title: "Try smolter" }] };
}

// routes/tasks/route.tsx
import { useLoaderData } from "@kasperrt/smolter/react";
import type { clientLoader } from "./clientLoader";

export { clientLoader } from "./clientLoader";

export default function Tasks() {
  const data = useLoaderData<typeof clientLoader>();

  return <ul>{data?.tasks.map((task) => (
    <li key={task.id}>{task.title}</li>
  ))}</ul>;
}

import { createDataRouter, defineRoute } from "@kasperrt/smolter/react";
import * as tasks from "./routes/tasks/route";

export const router = createDataRouter([
  defineRoute("/tasks", tasks),
], { browser: true });

import { RouterProvider, Routes } from "@kasperrt/smolter/react";
import { router } from "./router";

export function App() {
  return <RouterProvider router={router}>
    <Routes fallback={<p>Page not found.</p>} />
  </RouterProvider>;
}
